mapper.update:
update meal_order_candidate
set status = '3', update_time = sysdate()
where order_id = #{orderId} and status in ('0', '4') and user_id != #{acceptedUserId}

update meal_order_candidate
set expire_time = #{expireTime}, update_time = sysdate()
where order_id = #{orderId} and user_id = #{userId}

mapper.select:
select distinct c.order_id
from meal_order_candidate c
where c.user_id = #{userId}
  and c.order_id in

      #{orderId}

  and (c.status not in ('0', '4')
       or not exists (
           select 1 from meal_order o
           where o.order_id = c.order_id and o.status = '0' and o.del_flag = '0'
       ))
